CREATE TRIGGER _benmore_mfa_setup_nonce_insert AFTER INSERT ON _benmore_users BEGIN
			UPDATE _benmore_users SET mfa_setup_nonce=lower(hex(randomblob(16))) WHERE id=NEW.id;
		END

CREATE TRIGGER _benmore_mfa_setup_nonce_reset AFTER UPDATE OF password_hash,password_change_required ON _benmore_users BEGIN
			UPDATE _benmore_users SET mfa_setup_nonce=lower(hex(randomblob(16))) WHERE id=NEW.id;
		END
